-- REVIEW: isolate application objects from public/Data API grants.
DO $api$ DECLARE t text; r text; BEGIN
 FOREACH t IN ARRAY ARRAY['USER_ACCOUNT','ROLE','PERMISSION','USER_ROLE','ROLE_PERMISSION','LOGIN_SESSION','AUDIT_LOG','NOTIFICATION','DEPARTMENT','TITLE_CONFIG','TRAINING_SYSTEM','LECTURER','STUDENT','RESEARCH_AREA','LECTURER_AREA','IMPORT_JOB','THESIS_TERM','TERM_PHASE','TERM_PARAMETER','TERM_LECTURER','TERM_STUDENT','REGISTRATION','REGISTRATION_PREF','ASSIGNMENT_PLAN','ADVISOR_ASSIGNMENT','TOPIC','TOPIC_HISTORY','PROPOSAL','PROPOSAL_VERSION','REVIEW_GROUP','REVIEW_GROUP_MEMBER','PROPOSAL_REVIEW','THESIS_DOSSIER','GUIDANCE_PLAN','TASK','TASK_SUBMISSION','SUBMISSION_FILE','TASK_REVIEW','GUIDANCE_MEETING','PHASE_EVALUATION','FINAL_REPORT','DEFENSE_CONFIRMATION','DEFENSE_ELIGIBILITY','DEFERMENT_REQUEST','REVIEWER_ASSIGNMENT','ROOM','DEFENSE_COMMITTEE','COMMITTEE_MEMBER','DEFENSE_SESSION','COMMITTEE_STUDENT','DEFENSE_MINUTES','RUBRIC_CRITERIA','SCORE_ENTRY','SCORE_DETAIL','FINAL_RESULT','EXPORT_JOB','ACADEMIC_TERM_GRANT','GRANT_DEPARTMENT','RESEARCH_AREA_WORKFLOW','TERM_WORKFLOW','TERM_PHASE_WORKFLOW','ASSIGNMENT_PLAN_WORKFLOW','ASSIGNMENT_CHANGE','TOPIC_WORKFLOW','PROPOSAL_WORKFLOW','PROPOSAL_VERSION_WORKFLOW','REVIEW_GROUP_WORKFLOW','REVIEW_MEMBERSHIP_HISTORY','PROPOSAL_REVIEW_WORKFLOW','PROPOSAL_REVIEW_DECISION','REVIEW_COMMENT','DOSSIER_WORKFLOW','DOSSIER_FINALIZATION','DOSSIER_RECEIPT','DOSSIER_HISTORY','GUIDANCE_PLAN_WORKFLOW','PLAN_HISTORY','GUIDANCE_PERIOD','PERIOD_REQUIRED_STUDENT','WEEKLY_REPORT_OBLIGATION','TASK_WORKFLOW','TASK_PROGRESS_EVENT','TASK_HISTORY','SUBMISSION_WORKFLOW','PROGRESS_REVIEW','FILE_ASSET','SUBMISSION_ASSET','MEETING_WORKFLOW','MEETING_HISTORY','EVALUATION_WORKFLOW','EVALUATION_EVIDENCE','EVALUATION_HISTORY','OUTBOX_EVENT','IDEMPOTENCY_RECORD','pr2b_weekly_coverage'] LOOP
  EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC',t);
  FOREACH r IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
   IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=r) THEN
    EXECUTE format('REVOKE ALL ON TABLE public.%I FROM %I',t,r);
   END IF;
  END LOOP;
 END LOOP;
END $api$;
